package com.zungun.app

import android.content.ContentValues
import android.content.Context
import android.database.sqlite.SQLiteDatabase
import android.database.sqlite.SQLiteOpenHelper

class MessageStore(context:Context):SQLiteOpenHelper(context,"zungun-product-v1.db",null,1){
    data class Message(val messageId:String,val conversationId:String,val senderId:String,val body:String,val state:String,val clientCreatedAtMs:Long,val serverSequence:Long?,val deliveredAtMs:Long?,val lastError:String?)
    override fun onCreate(db:SQLiteDatabase){db.execSQL("CREATE TABLE messages(message_id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,sender_id TEXT NOT NULL,body TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('QUEUED','UNKNOWN','SENT','DELIVERED','CONFLICT')),client_created_at_ms INTEGER NOT NULL,server_sequence INTEGER,delivered_at_ms INTEGER,last_error TEXT)");db.execSQL("CREATE INDEX msg_conv_seq ON messages(conversation_id,server_sequence,client_created_at_ms)");db.execSQL("CREATE TABLE conversations(conversation_id TEXT PRIMARY KEY,peer_name TEXT NOT NULL,peer_code TEXT NOT NULL,peer_user_id TEXT NOT NULL)")}
    override fun onUpgrade(db:SQLiteDatabase,oldVersion:Int,newVersion:Int){}
    @Synchronized fun upsertConversation(id:String,name:String,code:String,userId:String){writableDatabase.insertWithOnConflict("conversations",null,ContentValues().apply{put("conversation_id",id);put("peer_name",name);put("peer_code",code);put("peer_user_id",userId)},SQLiteDatabase.CONFLICT_REPLACE)}
    @Synchronized fun conversations():List<Array<String>>{val out=mutableListOf<Array<String>>();readableDatabase.rawQuery("SELECT conversation_id,peer_name,peer_code,peer_user_id FROM conversations ORDER BY peer_name",null).use{c->while(c.moveToNext())out+=arrayOf(c.getString(0),c.getString(1),c.getString(2),c.getString(3))};return out}
    @Synchronized fun queue(messageId:String,conversationId:String,senderId:String,body:String,createdAtMs:Long){writableDatabase.insertOrThrow("messages",null,ContentValues().apply{put("message_id",messageId);put("conversation_id",conversationId);put("sender_id",senderId);put("body",body);put("state","QUEUED");put("client_created_at_ms",createdAtMs)})}
    @Synchronized fun get(id:String):Message?=readableDatabase.rawQuery("SELECT message_id,conversation_id,sender_id,body,state,client_created_at_ms,server_sequence,delivered_at_ms,last_error FROM messages WHERE message_id=?",arrayOf(id)).use{c->if(c.moveToFirst())row(c)else null}
    @Synchronized fun setState(id:String,state:String,error:String?=null,sequence:Long?=null,deliveredAtMs:Long?=null){writableDatabase.update("messages",ContentValues().apply{put("state",state);put("last_error",error);if(sequence!=null)put("server_sequence",sequence);if(deliveredAtMs!=null)put("delivered_at_ms",deliveredAtMs)},"message_id=?",arrayOf(id))}
    @Synchronized fun ingest(conversationId:String,messageId:String,senderId:String,body:String,createdAtMs:Long,sequence:Long,deliveredAtMs:Long?){val existing=get(messageId);if(existing!=null){if(existing.body!=body||existing.senderId!=senderId){setState(messageId,"CONFLICT","MESSAGE_ID_CONFLICT");return};setState(messageId,if(deliveredAtMs!=null)"DELIVERED" else maxState(existing.state),sequence=sequence,deliveredAtMs=deliveredAtMs);return};writableDatabase.insertOrThrow("messages",null,ContentValues().apply{put("message_id",messageId);put("conversation_id",conversationId);put("sender_id",senderId);put("body",body);put("state",if(deliveredAtMs!=null)"DELIVERED" else "SENT");put("client_created_at_ms",createdAtMs);put("server_sequence",sequence);if(deliveredAtMs!=null)put("delivered_at_ms",deliveredAtMs)})}
    @Synchronized fun messages(conversationId:String):List<Message>{val out=mutableListOf<Message>();readableDatabase.rawQuery("SELECT message_id,conversation_id,sender_id,body,state,client_created_at_ms,server_sequence,delivered_at_ms,last_error FROM messages WHERE conversation_id=? ORDER BY COALESCE(server_sequence,9223372036854775807),client_created_at_ms,message_id",arrayOf(conversationId)).use{c->while(c.moveToNext())out+=row(c)};return out}
    private fun row(c:android.database.Cursor)=Message(c.getString(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getLong(5),if(c.isNull(6))null else c.getLong(6),if(c.isNull(7))null else c.getLong(7),if(c.isNull(8))null else c.getString(8))
    private fun maxState(s:String)=if(s=="DELIVERED")"DELIVERED" else "SENT"
}
